import{_ as o,o as a,c as d,a6 as l}from"./chunks/framework.BIul5s8C.js";const i="/assets/image-20260619101411708.rvG-ay-T.png",c="/assets/image-20260619103053448.C__7H0Mo.png",r="/assets/image-20260619113753231.DvfRno6s.png",f=JSON.parse('{"title":"Linux命令","description":"","frontmatter":{},"headers":[],"relativePath":"zh/linux/commands.md","filePath":"zh/linux/commands.md"}'),p={name:"zh/linux/commands.md"};function t(h,e,n,s,u,m){return a(),d("div",null,e[0]||(e[0]=[l('<h1 id="linux命令" tabindex="-1">Linux命令 <a class="header-anchor" href="#linux命令" aria-label="Permalink to &quot;Linux命令&quot;">​</a></h1><h2 id="用户配置" tabindex="-1">用户配置 <a class="header-anchor" href="#用户配置" aria-label="Permalink to &quot;用户配置&quot;">​</a></h2><ul><li>超级用户（root）：命令提示符**#**，在linux系统下做任何事情，无限制</li><li>普通用户：命令提示符**$**，对linux系统操作受限</li></ul><p>新系统下，root用户无密码，使用<code>sudo passwd roo</code>t为root用户添加密码=</p><p><code>sudo</code>权限提升：使用时，身份由普通用户 -&gt; root</p><p>切换用户：<code>su 【用户名】</code>，不添加用户名，默认切换到root用户</p><p>root用户退出：<code>exit</code></p><p><img src="'+i+'" alt="image-20260619101411708"></p><h3 id="添加用户" tabindex="-1">添加用户 <a class="header-anchor" href="#添加用户" aria-label="Permalink to &quot;添加用户&quot;">​</a></h3><p><code>sudo useradd -m user1 -s /bin/bash</code></p><p>系统会在目录“/home”下建立一个名为user1的目录 -m 创建目录 -s 指定使用的脚本解析器（bash业界最流行的脚本解析器）</p><h3 id="配置密码" tabindex="-1">配置密码 <a class="header-anchor" href="#配置密码" aria-label="Permalink to &quot;配置密码&quot;">​</a></h3><p><code>sudo passwd user1</code></p><p>密码配置完成后，用户user1就可以用自己的用户和密码登录服务器</p><h3 id="删除用户" tabindex="-1">删除用户 <a class="header-anchor" href="#删除用户" aria-label="Permalink to &quot;删除用户&quot;">​</a></h3><p><code>sudo userdel -r user1</code></p><p><img src="'+c+'" alt="image-20260619103053448"></p><h2 id="目录及文件操作" tabindex="-1">目录及文件操作 <a class="header-anchor" href="#目录及文件操作" aria-label="Permalink to &quot;目录及文件操作&quot;">​</a></h2><h3 id="查看文件及目录" tabindex="-1">查看文件及目录 <a class="header-anchor" href="#查看文件及目录" aria-label="Permalink to &quot;查看文件及目录&quot;">​</a></h3><p><code>ls</code> 列出该指定目录下所有子文件和子目录</p><p><code>ls -a</code> 显示指定目录下所有子目录与文件（显示隐藏文件，例如以.开头）</p><p><code>ls -l</code> 列出指定目录下所有目录及文件的详细信息</p><p><code>ls–l /home/wilson</code> 每行列出的详细信息依次是：</p><p>文件类型与权限 硬连接数 文件所有者 文件所属组 文件大小 最近修改时间 文件名字</p><p>Linux不以后缀来区分文件类型，后面的9个字符表示文件的访问权限，分为3组，每组3位</p><p>第一组表示文件创建者的权限，第二组表示同组用户的权限，第三组表示其他用户的权限。每一组的三个字符分别表示对文件的读、写、</p><p>执行权限</p><p>各权限如下：r（读）、w（写）、x（执行）、-（没有设置权限）。每一组可以用一个数字表示，例如r-x:5,rw-:6,r--:4， 那么这三组就可以用3个数字表示，例如rwxr-xr-x:755，rw-r--r--:644</p><h3 id="改变工作目录" tabindex="-1">改变工作目录 <a class="header-anchor" href="#改变工作目录" aria-label="Permalink to &quot;改变工作目录&quot;">​</a></h3><p><code>cd</code> 改变工作目录</p><p><code>cd ~</code> 切换到自己的工作目录 /home/wilson</p><p><code>cd /</code> 切换到根目录</p><p><code>cd - </code>切换到上一次目录</p><p><code>. </code>表示当前目录</p><h3 id="查看当前工作目录" tabindex="-1">查看当前工作目录 <a class="header-anchor" href="#查看当前工作目录" aria-label="Permalink to &quot;查看当前工作目录&quot;">​</a></h3><p><code>pwd</code> 查看当前目录</p><h3 id="创建删除目录" tabindex="-1">创建删除目录 <a class="header-anchor" href="#创建删除目录" aria-label="Permalink to &quot;创建删除目录&quot;">​</a></h3><p><code>mkdir dir</code> 创建名为dir的文件夹，如果使用<code>sudo mkdir</code>，文件创建者就是root</p><p><code>rmdir</code>删除文件，只要对当前文件或文件夹有删除权限，就可以进行删除，而不用管文件的所有者是谁</p><p><code>rm -r</code> 删除文件夹</p><p><code>rm -r *</code>删除文件夹下所有文件</p><p><code>rm -rf</code> 删除文件夹下所有文件，且无提示</p><h3 id="拷贝文件和目录" tabindex="-1">拷贝文件和目录 <a class="header-anchor" href="#拷贝文件和目录" aria-label="Permalink to &quot;拷贝文件和目录&quot;">​</a></h3><p><code>cp file1 file2 </code>把指定的源文件复制到目标文件或把多个源文件复制到目标目录中</p><p><code>cp -i file1 day/</code> 将file1文件复制到day文件夹下，如果文件名重复，则提醒</p><p><code>cp -r /home/wilson /home/wilson1</code> 要拷贝一个目录，此时将同时拷贝该目录下的子目 录 和 文 件，目标文件也需要是一个目录</p><h3 id="移动文件" tabindex="-1">移动文件 <a class="header-anchor" href="#移动文件" aria-label="Permalink to &quot;移动文件&quot;">​</a></h3><p><code>mv /home/file1 . </code>将文件夹home下文件file1移动到当前目录下</p><h3 id="显示目录结构" tabindex="-1">显示目录结构 <a class="header-anchor" href="#显示目录结构" aria-label="Permalink to &quot;显示目录结构&quot;">​</a></h3><p><img src="'+r+'" alt="image-20260619113753231"></p><h3 id="改变目录或文件权限" tabindex="-1">改变目录或文件权限 <a class="header-anchor" href="#改变目录或文件权限" aria-label="Permalink to &quot;改变目录或文件权限&quot;">​</a></h3><p><code>chmod</code> 控制文件或目录的访问权限</p><p><strong>数字设定法</strong></p><p>首先了解用数字表示的属性的含义：0表示没有权限，1表示可执行权限，2表示可写权限，4</p><p>表示可读权限，然后将其相加。所以数字属性的格式应为3个从0到7的八进制数，其顺序是</p><p>（u）（g）（o）。例如，如果想让某个文件的所有者有&quot;读/写&quot;二种权限，需要把4（可读）+2</p><p>（可写）＝6（读/写).</p><p>例如：<code>chmod 644 hello.txt</code>执行后得到<code>-rw-r--r-- 1 wilson wilson 6 Jun 18 </code></p><p><code>22:47 hello.txt</code></p><ul><li>文件所有者（wilson）有读写权限</li><li>与文件所有者同组人有读权限</li><li>其他人有读权限</li></ul><h3 id="文件查找" tabindex="-1">文件查找 <a class="header-anchor" href="#文件查找" aria-label="Permalink to &quot;文件查找&quot;">​</a></h3><p>find查找条件可以是一个逻辑运算符not、and、or组成的复合条件</p><ul><li>and：逻辑与，在命令中用-a表示，表示只有当所给的条件都满足时，查找条件才满足</li><li>or：逻辑或，在命令中用-o表示，表示只要所给的条有一个满足，查找条件就满足</li><li>not：逻辑非，在命令中用！表示查找不满足所给条件的文件</li></ul><p>常用查找条件</p><ul><li><p><code>-empty</code> 查找大小为0的文件或者是空目录</p></li><li><p><code>-perm</code> 权限查找具有指定权限的文件和目录，权限的表示可以如711，644</p></li><li><p><code>-mmin n </code>查找n分钟以前文件内容被修改过的所有文件、</p><p><code>find . -mmin -60 </code>查找过去60分钟所修改的文件</p></li><li><p><code>-mtime n</code> 查找n天以前文件内容被修改过的所有文件</p></li><li><p><code>-xargs</code> 对符合条件的文件执行所给的Linux命令，而不询问用户是否需要执行该命令</p><p><code>find.-empty|xargsrm-rf</code>找到所有的空文件和空文件夹并删除</p></li><li><p><code>-size </code>查找指定文件大小的文件，+表示大于，-表示小于</p><p><code>find . -size +10M</code>查找大于10M的所有文件</p></li></ul><h3 id="列出文件系统整体磁盘空间使用情况" tabindex="-1">列出文件系统整体磁盘空间使用情况 <a class="header-anchor" href="#列出文件系统整体磁盘空间使用情况" aria-label="Permalink to &quot;列出文件系统整体磁盘空间使用情况&quot;">​</a></h3><p><code>df -h</code></p><h3 id="显示每个文件和目录的磁盘使用空间" tabindex="-1">显示每个文件和目录的磁盘使用空间 <a class="header-anchor" href="#显示每个文件和目录的磁盘使用空间" aria-label="Permalink to &quot;显示每个文件和目录的磁盘使用空间&quot;">​</a></h3><p><code>du -h</code></p><p><code>--max-depth=0</code>控制深度，最多往下统计多少个子目录，一般设置为<code>--max-depth=1</code></p><p>操作发现目录的每一级都显示，如果只想显示当前目录，<code>du -h --max-depth=1 /home/wilson</code></p><h3 id="文件查看" tabindex="-1">文件查看 <a class="header-anchor" href="#文件查看" aria-label="Permalink to &quot;文件查看&quot;">​</a></h3><p><code>cat hello.txt</code> 查看hello.txt文件</p><p><code>cat file1 &gt; file2</code> 重定向输出</p><p><code>echo wilson &gt;&gt; file1</code>添加输出</p><p><code>touch a.txt</code>创建a.txt空文件</p><p><code>head –n 10 main.cc</code>查看main.cc文件前10行</p><p><code>tail –n 10 main.cc</code>查看main.cc文件后10行</p><p><code>wc -l hello.txt</code>查看hello.txt文件总共多少行</p><h3 id="搜索文件内容" tabindex="-1">搜索文件内容 <a class="header-anchor" href="#搜索文件内容" aria-label="Permalink to &quot;搜索文件内容&quot;">​</a></h3><p>grep过滤器查找指定字符模式的文件，并显示含有此模式的所有行</p><p>被寻找的模式称为正则表达式</p><p><code>grep hello file1</code>在file1文件中查找hello，并显示含有hello的那一行</p><p>正则表达：</p><ul><li><code>^</code>:以什么开头，例如<code>ls –l|grep ^d</code>显示当前目录下的所有子目录的详细信息</li><li><code>$</code>:以什么结尾，例如<code>ls –l|grep c$</code>显示当前目录下以c结尾的文件</li></ul><p><code>grep -n</code> 在输出前加上匹配串所在的行号</p><h2 id="文档管理" tabindex="-1">文档管理 <a class="header-anchor" href="#文档管理" aria-label="Permalink to &quot;文档管理&quot;">​</a></h2><h3 id="tar-文件压缩打包" tabindex="-1">tar 文件压缩打包 <a class="header-anchor" href="#tar-文件压缩打包" aria-label="Permalink to &quot;tar 文件压缩打包&quot;">​</a></h3><p>常用参数：</p><ul><li>c：创建新的档案文件。</li><li>x：从档案文件中释放文件。</li><li>f：使用档案文件或设备。</li><li>v：在归档过程中显示处理的文件。</li><li>z：用gzip来压缩/解压缩文件，后缀名为.gz，加上该选项后可以将档案文件进行压缩。</li></ul><p>例如：<code>tar czvf source.tar.gz /home/wilson/*</code>将wilson文件夹下所有文件压缩</p><h3 id="gzip文件解压缩" tabindex="-1"><code>gzip</code>文件解压缩 <a class="header-anchor" href="#gzip文件解压缩" aria-label="Permalink to &quot;`gzip`文件解压缩&quot;">​</a></h3><p>常用参数：</p><ul><li>-d：将压缩文件进行解压。</li><li>-v：在压缩或解压过程中显示解压或压缩的文件。</li></ul><h3 id="scp远程copy文件" tabindex="-1">scp远程copy文件 <a class="header-anchor" href="#scp远程copy文件" aria-label="Permalink to &quot;scp远程copy文件&quot;">​</a></h3><p><code>scp filename username@ip:path</code></p><ul><li>filename：文件名称</li><li>username：copy到的目标主机的用户名</li><li>ip：目标主机IP</li><li>path：目标主机路径</li></ul><p><code>scp file3 king@192.168.4.52:~/</code>从本机copy到其他机器</p><p><code>scp king@192.168.4.52:~/file3 .</code>从其他机器copy到本机</p><p>如果scp的是文件夹，需要加-r</p><h3 id="无密钥登录" tabindex="-1">无密钥登录 <a class="header-anchor" href="#无密钥登录" aria-label="Permalink to &quot;无密钥登录&quot;">​</a></h3><ul><li><code>ssh-keygen</code>生成密钥和公钥 <ul><li>Linux路径~/.ssh</li><li>windows路径C:\\Users\\Administrator.ssh</li></ul></li><li><code>ssh-copy-id wilson@192.168.43.142</code>公钥复制到服务器的authorized_keys</li></ul><p>原理：</p><p><a href="https://ld246.com/article/1640830873031" target="_blank" rel="noreferrer">ssh连接过程</a></p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><p>Ctrl a 光标回到开头</p><p>Ctrl e 光标回到结尾</p>',107)]))}const b=o(p,[["render",t]]);export{f as __pageData,b as default};
